(function(){
  var R=window.EKV_RULES=window.EKV_RULES||[];
  [
   [/^बहुत सारी गलत कोशिशों की वजह से यह अस्थायी रूप से लॉक है — (\d+) मिनट बाद फिर कोशिश करें।$/, 'Temporarily locked because of too many wrong attempts — please try again after $1 minutes.'],
   [/^यह Staff ID \((.+?)\) पहले से बनी है।.*$/, 'This Staff ID ($1) already exists. Its link is in "All Staff" below; for a new Staff member write a different ID.'],
   [/^"(.+)" Staff List में नहीं मिला — Team Leader पहले से List में होना चाहिए।$/, '"$1" was not found in the Staff List — the Team Leader must already be in the List.'],
   [/^✅ (.+?) \((.+?)\) Staff List में जुड़ गया — Team Leader: (.+?)। Link तैयार है।$/, '✅ $1 ($2) added to the Staff List — Team Leader: $3. Link is ready.'],
   [/^✅ (.+?) \((.+?)\) Staff List में जुड़ गया — सीधा Admin के under। Link तैयार है।$/, '✅ $1 ($2) added to the Staff List — directly under Admin. Link is ready.'],
   [/^आप इस Vacancy पर पहले ही Apply कर चुके हैं \(Application ID: (.+?)\)।?$/, 'You have already applied for this Vacancy (Application ID: $1).'],
   [/^एक बार में ज़्यादा से ज़्यादा (\d+) Company चुन सकते हैं।$/, 'You can choose at most $1 Companies at a time.'],
   [/^इन सभी Company की Details आप पहले ही ले चुके हैं \(Request ID: (.+?)\)।.*$/, 'You have already taken the Details of all these Companies (Request ID: $1). Enter the same Request ID in "View my Details" to see them again — no payment will be charged again.'],
   [/^यह मोबाइल पहले से रजिस्टर है और आपकी Registration चालू है। आपकी Karigar ID: (.+)$/, 'This mobile is already registered and your Registration is active. Your Karigar ID: $1'],
   [/^यह फॉर्म अभी-अभी जमा हुआ है — कृपया (\d+) सेकंड बाद दोबारा कोशिश करें।$/, 'This form was just submitted — please try again after $1 seconds.'],
   [/^अपना अनुभव कम-से-कम (\d+) अक्षर में लिखें।$/, 'Write your experience in at least $1 characters.'],
   [/^Comment (\d+) अक्षर से छोटा रखें।$/, 'Keep the comment under $1 characters.'],
   [/^Line (\d+): Grade \/ काम चुनें \(या Other में लिखें\)।$/, 'Line $1: Choose a Grade / work (or write in Other).'],
   [/^Line (\d+) \((.+?)\): Candidate की सही संख्या लिखें \(कम से कम 1\)।$/, 'Line $1 ($2): Enter the correct number of Candidates (at least 1).'],
   [/^"(.+?)" दो बार जुड़ा है — एक ही Line में संख्या जोड़ दें।$/, '"$1" has been added twice — add the number in a single Line.'],
   [/^Line (\d+) \((.+?)\): Other है, इसलिए अपना Rate \(₹\) लिखें।$/, 'Line $1 ($2): This is Other, so enter your own Rate (₹).'],
   [/^(PTY\d+|PAY\d+|DUE\d+|[A-Z]{2,5}\d+) नहीं मिला।?$/, '$1 was not found.'],
   [/^(.+?) नहीं मिला\.?$/, '$1 was not found.'],
   [/^(\S+) बन गया — (\d+) तरह के (\d+) आदमी, कुल (.+?) (हर महीने|\(एक बार\))(.*)$/, function(){return null;}],
   [/^रकम बकाये \((.+?)\) से ज़्यादा है।$/, 'The amount is more than the due ($1).'],
   [/^(\S+) अपडेट हो गया।(.*)$/, '$1 updated.$2'],
   [/^(\S+) बंद — अब इसका Alert नहीं आएगा(.*)$/, '$1 closed — its Alert will no longer come$2'],
   [/^(\S+) बंद — आगे कोई नया बकाया नहीं बनेगा(.*)$/, '$1 closed — no new dues will be created from now on$2'],
   [/^'(.+?)' शीट नहीं मिली$/, "The '$1' sheet was not found"],
   [/^'(.+?)' शीट नहीं मिली — कृपया Admin से संपर्क करें।$/, "The '$1' sheet was not found — please contact Admin."],
   [/^आपका अनुरोध \((.+?)\) दर्ज हो गया। Address आपकी Email \((.+?)\) पर भेजा जाएगा।$/, 'Your request ($1) has been recorded. The Address will be sent to your Email ($2).'],
   [/^यह Request पूरी हो चुकी है \((.+?)\)।$/, 'This request is already completed ($1).'],
   [/^Address (.+?) की Email पर भेज दिया गया \((.+?)\)(.*)$/, 'Address was sent to $1\'s Email ($2)$3'],
   [/^अभी इस Request पर कोई Address 'Reply के इंतज़ार' में नहीं है \(Status: (.+?)\)।$/, "No Address is currently 'waiting for a Reply' on this request (Status: $1)."],
   [/^आपके Batch \((.+?)\) की शुरू होने की तारीख अभी तय नहीं हुई है।$/, 'The start date of your Batch ($1) has not been decided yet.'],
   [/^आपके (.+?) की Training पूरी हो चुकी है, इसलिए अब Attendance नहीं लगती।$/, 'The Training of your $1 is complete, so Attendance is no longer marked.'],
   [/^Attendance Sheet में 'Day (\d+)' का कॉलम नहीं मिला — कृपया Admin से संपर्क करें।$/, "The 'Day $1' column was not found in the Attendance Sheet — please contact Admin."],
   [/^आज \(Day (\d+)\) की Attendance पहले से लगी हुई है।$/, "Today's (Day $1) Attendance is already marked."],
   [/^Day (\d+) की Attendance \(P\) नहीं है, इसलिए इसकी File नहीं मिल सकती।$/, 'There is no Attendance (P) for Day $1, so its File cannot be given.'],
   [/^Day (\d+) की File आप (.+?) को Download कर चुके हैं — यह सिर्फ़ एक बार मिलती है।.*$/, 'You already downloaded the Day $1 File on $2 — it is available only once. Contact us on WhatsApp if needed.'],
   [/^इन ID का कोई Data Database में नहीं मिला \(शायद Typo है\): (.+)$/, 'No data was found in the Database for these IDs (maybe a typo): $1'],
   [/^Server में अस्थायी दिक्कत आई, कृपया थोड़ी देर में फिर कोशिश करें। \((.*)\)$/, 'A temporary problem occurred on the server — please try again shortly. ($1)'],
   [/^कृपया (\d+) सेकंड बाद दोबारा भेजें।$/, 'Please send again after $1 seconds.']
  ].forEach(function(r){ if(typeof r[1]==='string') R.push(r); });
})();
